-- users: company employees. Accounts are created in advance by an admin;
-- there is no self sign-up. The first admin is created at startup from
-- INITIAL_ADMIN_EMAIL. Email is the only way to sign in.
-- id:         Sonyflake id generated by the app, e.g. 587364927401230337
-- email:      always lowercase, e.g. 'ali@example.com'
-- name:       e.g. 'Ali Valiyev'
-- role:       'admin' manages users, 'user' only signs in, e.g. 'user'
-- enabled:    e.g. false = cannot sign in, all sessions are ended
-- created_at: e.g. '2026-10-15 09:00:00+05'
-- updated_at: e.g. NULL until the first change
CREATE TABLE users (
    id         BIGINT PRIMARY KEY,
    email      TEXT        NOT NULL UNIQUE CHECK (email = lower(email)),
    name       TEXT        NOT NULL,
    role       TEXT        NOT NULL DEFAULT 'user' CHECK (role IN ('admin', 'user')),
    enabled    BOOLEAN     NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ
);

-- signin_requests: one row per "enter email" step; a magic link is emailed for it.
-- The link works only on the device that started the request: it holds the
-- device secret (cookie in a browser, stored by the app). A link opened
-- anywhere else does nothing. Rows are created only for existing, enabled users.
-- Data moves table to table: when the link is used, the needed data is copied
-- to sessions (same id) and the row is deleted. Rows that never become a
-- session are deleted by the periodic cleanup.
-- id:           Sonyflake id, kept in sessions and ended_sessions, e.g. 587364927401230338
-- user_id:      e.g. 587364927401230337
-- token_hash:   hash of the magic link token, e.g. sha256('q8Zk...')
-- secret_hash:  hash of the device secret only the requesting device knows
-- device:       device info sent by the client, or parsed from User-Agent,
--               e.g. '{"name":"iPhone 15","os":"iOS 18","client":"MyApp 2.4","source":"client"}'
--               e.g. '{"name":"","os":"","client":"curl 8.5.0","source":"user_agent"}'
-- requested_ip: IP the email was entered from, e.g. '203.0.113.7'
-- requested_at: when the email was entered, e.g. '2026-10-15 09:00:00+05'
-- expires_at:   e.g. requested_at + 10 minutes
CREATE TABLE signin_requests (
    id           BIGINT      PRIMARY KEY,
    user_id      BIGINT      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   TEXT        NOT NULL UNIQUE,
    secret_hash  TEXT        NOT NULL,
    device       JSONB       NOT NULL,
    requested_ip INET,
    requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at   TIMESTAMPTZ NOT NULL
);

-- Rate limit: how many signin requests a user made in the last hour.
CREATE INDEX signin_requests_user_id_requested_at_idx ON signin_requests (user_id, requested_at);

-- sessions: a signed-in device (session = device, as in Telegram).
-- Created from a signin request when its link is used: the request's id and
-- device are copied here and the request is deleted. When the session ends,
-- its data is copied to ended_sessions and the row is deleted.
-- id:           same as the signin request's id, e.g. 587364927401230338
-- user_id:      e.g. 587364927401230337
-- token_hash:   hash of the current refresh token, e.g. sha256('r7Xp...')
-- device:       from signin_requests.device
-- started_ip:   IP the link was opened from, e.g. '203.0.113.7'
-- started_at:   when the user signed in, e.g. '2026-10-15 09:01:30+05'
-- current_ip:   IP of the latest request, e.g. '198.51.100.4'
-- current_at:   time of the latest request, updated together with current_ip;
--               shown as "last active" in the device list
-- expires_at:   e.g. started_at + 30 days
CREATE TABLE sessions (
    id           BIGINT      PRIMARY KEY,
    user_id      BIGINT      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   TEXT        NOT NULL UNIQUE,
    device       JSONB       NOT NULL,
    started_ip   INET,
    started_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    current_ip   INET,
    current_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    expires_at   TIMESTAMPTZ NOT NULL
);

CREATE INDEX sessions_user_id_idx ON sessions (user_id);

-- ended_sessions: archive of ended sessions. When a session ends, its row is copied here
-- column by column (same names, 1:1 with sessions) and deleted from sessions.
-- How it ended is kept in one JSON column. Only signin requests that became
-- a session end up here.
-- id ... expires_at: same as in sessions
-- ended: how the session ended,
--        e.g. '{"at":"2026-10-20T18:30:00+05:00","reason":"terminated","by":587364927401230337,"by_session":587364927401230999}'
--        at:         when it ended
--        reason:     'logout', 'terminated', 'expired' or 'disabled'
--        by:         user who ended it; null when ended by the system
--        by_session: session (device) it was ended from; null when ended by the system
CREATE TABLE ended_sessions (
    id         BIGINT      PRIMARY KEY,
    user_id    BIGINT      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    device     JSONB       NOT NULL,
    started_ip INET,
    started_at TIMESTAMPTZ NOT NULL,
    current_ip INET,
    current_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    ended      JSONB       NOT NULL CHECK (ended->>'reason' IN ('logout', 'terminated', 'expired', 'disabled'))
);

CREATE INDEX ended_sessions_user_id_idx ON ended_sessions (user_id);
